def minPath(grid, k):
    n = len(grid)

    # Find the cell with value 1 (the minimum value)
    start_r, start_c = 0, 0
    for i in range(n):
        for j in range(n):
            if grid[i][j] == 1:
                start_r, start_c = i, j
                break
        else:
            continue
        break

    path = [1]
    r, c = start_r, start_c

    directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]

    for _ in range(k - 1):
        best_val = float('inf')
        best_r, best_c = r, c
        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < n and 0 <= nc < n:
                if grid[nr][nc] < best_val:
                    best_val = grid[nr][nc]
                    best_r, best_c = nr, nc
        path.append(best_val)
        r, c = best_r, best_c

    return path
